import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { subscriptions } from 'kea-subscriptions'

import { FileSystemEntry } from '~/queries/schema/schema-general'

import { panelLayoutLogic } from '../../panelLayoutLogic'
import { projectTreeLogic } from '../../ProjectTree/projectTreeLogic'

export const FILES_TREE_KEY = 'navbar-files'
export const FILES_STARRED_TREE_KEY = 'navbar-files-starred'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface navFilesTabLogicValues {
    searchTerm: string // projectTreeLogic
    viableItems: FileSystemEntry[] // projectTreeLogic
    folderRevealCount: number
    folderToReveal: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface navFilesTabLogicActions {
    openFolder: (folder: string) => {
        folder: string
    }
}

export type navFilesTabLogicType = MakeLogicType<navFilesTabLogicValues, navFilesTabLogicActions>

export const navFilesTabLogic = kea<navFilesTabLogicType>([
    path(['layout', 'panel-layout', 'navbar', 'tabs', 'navFilesTabLogic']),
    connect(() => ({
        values: [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }), ['searchTerm', 'viableItems']],
        logic: [projectTreeLogic({ key: FILES_STARRED_TREE_KEY, root: 'shortcuts://', shortcutScope: 'files' })],
    })),
    actions({ openFolder: (folder: string) => ({ folder }) }),
    reducers({
        folderRevealCount: [0, { openFolder: (state) => state + 1 }],
        folderToReveal: [
            null as string | null,
            {
                openFolder: (_, { folder }) => folder || null,
                [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actionTypes.scrollToView]: (
                    state,
                    { item }: { item: FileSystemEntry }
                ) => (item.type === 'folder' && item.path === state ? null : state),
            },
        ],
    }),
    listeners(() => ({
        openFolder: ({ folder }) => {
            panelLayoutLogic.actions.setNavExperimentTab('files')
            panelLayoutLogic.actions.showLayoutNavBar(true)
            panelLayoutLogic.actions.clearActivePanelIdentifier()
            panelLayoutLogic.actions.showLayoutPanel(false)
            if (panelLayoutLogic.values.isLayoutNavCollapsed) {
                panelLayoutLogic.actions.setNavOverlayOpen(true)
            }
            const tree = projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' })
            tree.actions.clearSearch()
            tree.actions.setSortMethod('folder')
            tree.actions.setOnlyFolders(false)
            tree.actions.assureVisibility({ type: 'folder', ref: folder })
            if (!tree.values.expandedFolders.includes(`project://${folder}`)) {
                tree.actions.toggleFolderOpen(`project://${folder}`, true)
            }
        },
        [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actionTypes.setSearchTerm]: ({
            searchTerm,
        }: {
            searchTerm: string
        }) => {
            projectTreeLogic({
                key: FILES_STARRED_TREE_KEY,
                root: 'shortcuts://',
                shortcutScope: 'files',
            }).actions.setSearchTerm(searchTerm)
        },
        [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actionTypes.clearSearch]: () => {
            projectTreeLogic({
                key: FILES_STARRED_TREE_KEY,
                root: 'shortcuts://',
                shortcutScope: 'files',
            }).actions.clearSearch()
        },
    })),
    subscriptions(({ values }) => ({
        viableItems: (items: FileSystemEntry[]) => {
            const folder = items.find((item) => item.type === 'folder' && item.path === values.folderToReveal)
            if (folder) {
                projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actions.scrollToView(folder)
            }
        },
    })),
])
